(7486509, 1191517, 94815, '<td valign="top">Difficult to make work normally but this pulls it off beautifully. The swirls give a frenetic, almost aural sense of the sound and composition is perfectly dizzying.</td>', 'Difficult to make work normally but this pulls it off beautifully. The swirls give a frenetic, almost aural sense of the sound and composition is perfectly dizzying.', '2016-12-08 22:47:48.000000', NULL, 1),
(7486511, 1191612, 94815, '<td valign="top">This could be called an intellectual eruption. Or maybe Revenge of Writing - facts finally rebelling against the dizzying effects of fake news and conspiracy theories.</td>', 'This could be called an intellectual eruption. Or maybe Revenge of Writing - facts finally rebelling against the dizzying effects of fake news and conspiracy theories.', '2016-12-08 22:53:06.000000', NULL, 1),
